insert into public.pets (id, name, species, breed, age_label, intake_date, tags, status, summary, foster_available, sex, size, color, weight_lbs, spayed_neutered, good_with_kids, good_with_dogs, good_with_cats, energy_level, housing, source_name, source_url, source_animal_id, image_path, gallery_urls)
values
  (md5('dekalb:51968937')::uuid, 'Chilly Win', 'Dog', 'Mixed breed', '5 years 9 months', '2023-01-30', array['big-dog', 'in-foster', 'shy', 'affectionate', 'house-trained']::text[], 'Available', 'Chilly Win (AKA Cheerio) is enjoying life in a foster home, but her wish for 2024 is to have a family of her own. She is a sweet and loving girl, house trained and quiet. She is dog friendly and enjoys playing with her doggy foster siblings. She also likes toys and bones and can entertain herself. She is nervous meeting new people, but once she is comfortable, she is loving, cuddly, and devoted. She is medium energy and nondestructive in the home. She is also a great sleeper and will let you sleep in, if that''s your thing! Cheerio needs a patient owner who understands that going slow with her will bring many future rewards! Because of her fear of new people, we recommend a home with either no kids or kids 13+.', false, 'Female', 'Large', 'Brown and white', 66, 'Yes', 'Unknown', 'Yes', 'Unknown', 'Medium', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=51968937&cid=97&tid=Dog', '51968937', 'dekalb/51968937/1.jpg', array['dekalb/51968937/2.jpg', 'dekalb/51968937/3.jpg']::text[]),
  (md5('dekalb:61714665')::uuid, 'Sheffield', 'Dog', 'Mixed breed', '5 years 1 month', '2026-09-11', array['big-dog']::text[], 'Available', 'Sheffield is a 5 years 1 month old male dog with a Grey and white coat. Come meet Sheffield at the shelter, or ask about taking Sheffield home.', true, 'Male', 'Extra large', 'Grey and white', 92, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61714665&cid=97&tid=Dog', '61714665', 'dekalb/61714665/1.jpg', array['dekalb/61714665/2.jpg', 'dekalb/61714665/3.jpg']::text[]),
  (md5('dekalb:57022832')::uuid, 'Nita', 'Dog', 'Mixed breed', '10 years', '2024-10-05', array['senior', 'in-foster', 'affectionate']::text[], 'Available', 'Nita is an 8 yr. old pup, a sweet senior, who would prefer to spend her retirement in a loving home rather than a shelter. She''s only 38 lbs, cute with her black and tan coloring and would pass breed restrictions. She''s friendly to all, low key and chill. She saw a dog in another yard and wagged her tail in greeting. We get the feeling Nita, who is a no muss, no fuss kind of girl, would make an easy addition to your home. She deserves some pampering. How about taking her home and doing just that?', false, 'Female', 'Medium', 'Black and tan', 60, 'Yes', 'Unknown', 'Unknown', 'Unknown', 'Low', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=57022832&cid=97&tid=Dog', '57022832', 'dekalb/57022832/1.jpg', array['dekalb/57022832/2.jpg', 'dekalb/57022832/3.jpg']::text[]),
  (md5('dekalb:60862835')::uuid, 'Cookie Crisp', 'Cat', 'Mixed breed', '6 months', '2026-04-24', array['kitten', 'in-foster']::text[], 'Available', 'Cookie Crisp is a 6 months old male cat with a Black coat. Come meet Cookie Crisp at the shelter, or ask about taking Cookie Crisp home.', false, 'Male', 'Small', 'Black', 4, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=60862835&cid=97&tid=Cat', '60862835', 'dekalb/60862835/1.jpg', array['dekalb/60862835/2.jpg']::text[]),
  (md5('dekalb:61711856')::uuid, 'Sombra', 'Dog', 'Mixed breed', '1 year', '2026-09-09', array['big-dog']::text[], 'Available', 'Sombra is a 1 year old male dog with a Black and white coat. Come meet Sombra at the shelter, or ask about taking Sombra home.', true, 'Male', 'Large', 'Black and white', 58, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61711856&cid=97&tid=Dog', '61711856', 'dekalb/61711856/1.jpg', array['dekalb/61711856/2.jpg', 'dekalb/61711856/3.jpg']::text[]),
  (md5('dekalb:61823979')::uuid, 'Marvo', 'Dog', 'Mixed breed', '5 years', '2026-09-30', array['big-dog', 'in-foster']::text[], 'Available', 'Marvo is a 5 years old male dog with a White coat. Come meet Marvo at the shelter, or ask about taking Marvo home.', false, 'Male', 'Large', 'White', 54, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61823979&cid=97&tid=Dog', '61823979', 'dekalb/61823979/1.jpg', array['dekalb/61823979/2.jpg']::text[]),
  (md5('dekalb:57415494')::uuid, 'Spot', 'Dog', 'Mixed breed', '6 years 10 months', '2025-10-07', array['big-dog', 'in-foster', 'affectionate', 'house-trained', 'good-with-kids']::text[], 'Available', 'Meet Spot, the ultimate sweetheart and a true blockhead in the best sense because the size of his head is matched only by the size of his heart. After spending a long time in foster, his family has discovered so many wonderful things about this big, goofy lovebug. Spot is a ball chasing pro who loves tossing toys in the air and proudly carrying them around. He is also a top tier tester of "indestructible" toys (spoiler: they rarely pass his test). Despite his playful side, Spot is completely non destructive and can entertain himself when left alone. He has no separation anxiety and does not require a crate, though he will tolerate being placed in one. This cuddle bug adores ear and belly rubs, gives the sweetest kisses, and is incredibly gentle when taking treats. He is very treat motivated, loves car rides, and greets his friends with the kind of excitement that makes his whole body wiggle. Around his puppy foster sibling, his playful side comes to life and he looks like an overgrown puppy himself. Spot is dog friendly, loves kids, and has loved meeting every new person. He is house trained, quick to take care of business outside, and charms everyone with his adorable head tilts and soulful eyes. He also loves being close to his people, happily alternating between oversized lapdog and loyal shadow. At five years old, almost six, Spot is an easygoing, chill, affectionate companion who will melt hearts everywhere. He is simply a big, goofy sweetheart who deserves someone who will love him with all their heart because that is exactly what he will give in return.', false, 'Male', 'Large', 'White and tan', 60, 'Yes', 'Yes', 'Yes', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=57415494&cid=97&tid=Dog', '57415494', 'dekalb/57415494/1.jpg', array['dekalb/57415494/2.jpg', 'dekalb/57415494/3.jpg']::text[]),
  (md5('dekalb:61439723')::uuid, 'Carlton', 'Cat', 'Mixed breed', '5 years 3 months', '2026-07-26', '{}'::text[], 'Available', 'Carlton is a 5 years 3 months old male cat with a Grey and white coat. Come meet Carlton at the shelter, or ask about taking Carlton home.', true, 'Male', 'Medium', 'Grey and white', 7, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61439723&cid=97&tid=Cat', '61439723', 'dekalb/61439723/1.jpg', array['dekalb/61439723/2.jpg', 'dekalb/61439723/3.jpg']::text[]),
  (md5('dekalb:59056342')::uuid, 'Princess Peach', 'Dog', 'Mixed breed', '5 years 2 months', '2025-08-05', array['big-dog', 'in-foster', 'affectionate', 'house-trained', 'good-with-kids']::text[], 'Available', 'Princess Peach has some amazing notes from her time in a foster home but the one that really stood out was this-"I have fostered some 50 dogs over the years and she is probably the smartest. She is definitely the most affectionate and loving." WOW! "She is extremely bright, wants to please.... is always ready for an adventure....She is also content to just sit by your side (mostly on you) for hours and snore while you watch TV and scratch her." She''s housetrained and has done well with kids over 8. Princess Peach sounds like a peach. If you''re looking for a hiking/walking buddy, Princess Peach can walk for hours. If you''re looking for an affectionate dog who''s always happy to see you-Princess Peach again. She does need to be an only dog but a dog this good is really all you need. Meet her today.', false, 'Female', 'Large', 'Tan and white', 69, 'Yes', 'Yes', 'No', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=59056342&cid=97&tid=Dog', '59056342', 'dekalb/59056342/1.jpg', array['dekalb/59056342/2.jpg', 'dekalb/59056342/3.jpg', 'dekalb/59056342/4.jpg']::text[]),
  (md5('dekalb:49984504')::uuid, 'March Ice', 'Dog', 'Mixed breed', '5 years 6 months', '2026-07-23', array['big-dog', 'in-foster', 'affectionate', 'good-with-kids']::text[], 'Available', 'March yourself right in to the shelter to meet March Ice now! March Ice is 5 years old and 51 pounds. She lived in a home for 3 years but was surrendered to the shelter through no fault of her own. She has lived with kids, is house and crate trained and has good in home notes. Her owner called her an overall good dog, who is playful and affectionate. She is friendly with other dogs as well just not that interested in playing. She is being treated for some hair loss but once that''s taken care of, we think March Ice is going to look pretty darn nice. March Ice would love to have a home again. She''s ready to go today!!', false, 'Female', 'Large', 'Tan and white', 48, 'Yes', 'Yes', 'Yes', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=49984504&cid=97&tid=Dog', '49984504', 'dekalb/49984504/1.jpg', array['dekalb/49984504/2.jpg', 'dekalb/49984504/3.jpg']::text[]),
  (md5('dekalb:61926443')::uuid, 'E. Aster Bunnymund', 'Rabbit', 'Rabbit', '1 year 6 months', '2026-10-18', '{}'::text[], 'Available', 'E. Aster Bunnymund is a 1 year 6 months old female rabbit with a White and black coat. Come meet E. Aster Bunnymund at the shelter, or ask about taking E. Aster Bunnymund home.', true, 'Female', 'Large', 'White and black', null, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61926443&cid=97&tid=other', '61926443', 'dekalb/61926443/1.jpg', '{}'::text[]),
  (md5('dekalb:46847604')::uuid, 'Jett', 'Dog', 'Mixed breed', '6 years 1 month', '2026-07-31', array['big-dog', 'shy', 'affectionate', 'house-trained']::text[], 'Available', 'Jett is handsome good boy. We are fairly certain that he is housetrained. A volunteer said, "This is a very good dog. Very easy to handle and very friendly. No issues at all." He has been a tad shy here and likely had a good home at one time. During his photo shoot he was independent and interested in sniffing so those neighborhood walks for him will be hi favorite thing. We know he is smart but waiting for his family (yours). You''ll see all the good stuff he knows at six years old at home. Be his family. Okay?', true, 'Male', 'Large', 'Brown and black', 63, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=46847604&cid=97&tid=Dog', '46847604', 'dekalb/46847604/1.jpg', array['dekalb/46847604/2.jpg', 'dekalb/46847604/3.jpg']::text[]),
  (md5('dekalb:61856575')::uuid, 'Izzy Lightwood', 'Dog', 'Mixed breed', '4 years', '2026-10-05', '{}'::text[], 'Available', 'Izzy Lightwood is a 4 years old female dog with a Grey and white coat. Come meet Izzy Lightwood at the shelter, or ask about taking Izzy Lightwood home.', true, 'Female', 'Medium', 'Grey and white', 36, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61856575&cid=97&tid=Dog', '61856575', 'dekalb/61856575/1.jpg', '{}'::text[]),
  (md5('dekalb:60183372')::uuid, 'Whirlwind', 'Dog', 'Mixed breed', '4 years 6 months', '2026-01-29', array['big-dog', 'in-foster', 'affectionate']::text[], 'Available', 'This Whirlwind took volunteers by storm with her captivating personality and gorgeous good looks. She''s 6 years old and 59 lbs, a blonde shepherd-looking girl with black on her face, tall ears and a fluffy curly tail. She was found in a wooded area with another dog (Bigheart) and they appeared to be very attached. (Bigheart is also available for adoption.) Whirlwind walks nicely on leash but what really stands out about her is how very sweet she is. She is always smiling, happy and loves affection. We don''t know why she was lost or abandoned but she deserves a loving home. She''s simply the best!', false, 'Female', 'Large', 'Beige and black', 55, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=60183372&cid=97&tid=Dog', '60183372', 'dekalb/60183372/1.jpg', array['dekalb/60183372/2.jpg', 'dekalb/60183372/3.jpg']::text[]),
  (md5('dekalb:61645068')::uuid, 'Cadillac', 'Dog', 'Mixed breed', '4 years 2 months', '2026-08-29', array['big-dog', 'affectionate']::text[], 'Available', 'Meet Cadillac, a sweet, 4 year old dog, not a high performing car! This is a gal who is easy to handle on leash and takes treats politely. She''s motivated by treats so should learn commands easily. Cadillac catches treats in midair, and waited with her feet doing a tap dance for the next treat! She loved playing with a squeaky toy and played with it for a long time. Laser-focused Cadillac watched her handler closely for directions and was a delightful dog to see in action! Cadillac is waiting for her home, so meet her soon.', true, 'Female', 'Large', 'Grey and white', 48, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61645068&cid=97&tid=Dog', '61645068', 'dekalb/61645068/1.jpg', array['dekalb/61645068/2.jpg', 'dekalb/61645068/3.jpg']::text[]),
  (md5('dekalb:61730773')::uuid, 'Evangeline', 'Dog', 'Mixed breed', '3 years 1 month', '2026-09-14', array['big-dog', 'in-foster', 'affectionate', 'house-trained']::text[], 'Available', 'Evangeline finds people a little scary at the shelter so she needs some time to get to know a person. When her favorite person took her out into a yard for her photo shoot, she met several people and she actually did great without knowing them. She warmed up right away and showed her playful side. She is a super sweet girl who takes treats gently and is fairly easy to walk. She acts like she''s house trained too. She''s a really really good girl. She will do even better when she is comfortable in a home and once you''re one of her people, she''s very loyal and she will love you forever. Come meet her.', false, 'Female', 'Large', 'White', 43, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61730773&cid=97&tid=Dog', '61730773', 'dekalb/61730773/1.jpg', array['dekalb/61730773/2.jpg', 'dekalb/61730773/3.jpg']::text[]),
  (md5('dekalb:61183556')::uuid, 'Willy-nilly', 'Cat', 'Mixed breed', '5 months', '2026-06-13', array['kitten', 'in-foster']::text[], 'Available', 'Willy-nilly is a 5 months old female cat with a White and black coat. Come meet Willy-nilly at the shelter, or ask about taking Willy-nilly home.', false, 'Female', 'Small', 'White and black', 3, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61183556&cid=97&tid=Cat', '61183556', 'dekalb/61183556/1.jpg', array['dekalb/61183556/2.jpg', 'dekalb/61183556/3.jpg']::text[]),
  (md5('dekalb:57452843')::uuid, 'Tahoe', 'Dog', 'Mixed breed', '6 years 10 months', '2024-12-13', array['in-foster', 'shy', 'affectionate']::text[], 'Available', 'Tahoe has the most adorable permanent puppy face even though he''s 5 years old. He''s a very sweet pup and a perfect gentleman when he''s outside of his kennel. He''s not a fan of living in the shelter but you can help by giving this wonderful boy a good home. Volunteers said he''s a bit shy at first but warms up quickly. He adores pets, is a kind soul and a wannabe couch potato. He takes treats gently, hasn''t quite figured out what he''s supposed to do with toys and is so good looking you''ll be proud to take him in and show him off on walks. Only 43 lbs and needs out of the shelter ASAP!!', false, 'Male', 'Medium', 'Black and white', 57, 'Yes', 'Unknown', 'Unknown', 'Unknown', 'Low', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=57452843&cid=97&tid=Dog', '57452843', 'dekalb/57452843/1.jpg', array['dekalb/57452843/2.jpg', 'dekalb/57452843/3.jpg']::text[]),
  (md5('dekalb:61751261')::uuid, 'Wealthy', 'Dog', 'Mixed breed', '4 years 1 month', '2026-09-16', array['big-dog', 'affectionate']::text[], 'Available', 'You''ll be wealthy in the ways that count when you bring this handsome boy home. Wealthy is 4 years old and 66 pounds with fabulous ears that go way up and then flop over at the very top. He impressed volunteers with how calmly he walked out into a yard for his photos to be taken. He does have a bit of a worried look on his face but when he saw another dog he lit up with joy. He got up on a lounge chair with volunteers and appreciated getting some love and treats which he took gently. Wealthy needs a loving home where he can relax and learn to socialize at his own pace. Yours?', true, 'Male', 'Large', 'Brown and white', 66, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61751261&cid=97&tid=Dog', '61751261', 'dekalb/61751261/1.jpg', array['dekalb/61751261/2.jpg', 'dekalb/61751261/3.jpg']::text[]),
  (md5('dekalb:61823987')::uuid, 'Padma Patil', 'Dog', 'Mixed breed', '7 years', '2026-09-30', array['big-dog', 'affectionate']::text[], 'Available', 'Meet adorable, friendly, gentle and loving Padma Patil, a sweet 7 year old! When she was out for her pictures, she stole the hearts of the staff and volunteers who met her! Padma happily basked in all the attention. She met several people outside of the building, and went up to each one as if to say "Hello! I''d love to go home!" Padma Patil came in as a stray and is waiting for someone to choose her. She''s a gentle and loving dog who would be delighted to have a pile of soft blankets to rest on. Come meet her today!', true, 'Female', 'Large', 'White and black', 66, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61823987&cid=97&tid=Dog', '61823987', 'dekalb/61823987/1.jpg', array['dekalb/61823987/2.jpg', 'dekalb/61823987/3.jpg']::text[]),
  (md5('dekalb:54034403')::uuid, 'Rigby', 'Dog', 'Mixed breed', '3 years 7 months', '2023-08-25', array['in-foster', 'shy']::text[], 'Available', 'Rigby arrived at the shelter in August 2023 when he was just a few months old. He is one of 7 dogs who have waited for over 2 years for a court case to be resolved. No dog should have to grow up in a shelter and we''ve watched him grow from 14 lbs to 45 lbs. Rigby is finally ready for his forever home! He loves to run laps in the play yard when he has the chance! He is described as "shy" but he loves to give kisses! Take one look at his perky ears and his small stature and he will win your heart. Rigby has been the underdog for way too long! Load your car with tempting treats, a nice soft bed, and give Rigby the love he has waited for!', false, 'Male', 'Medium', 'Tan and white', 46, 'Yes', 'Unknown', 'Unknown', 'Unknown', 'High', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=54034403&cid=97&tid=Dog', '54034403', 'dekalb/54034403/1.jpg', array['dekalb/54034403/2.jpg', 'dekalb/54034403/3.jpg']::text[]),
  (md5('dekalb:61202963')::uuid, 'Viper', 'Dog', 'Mixed breed', '4 years 4 months', '2026-06-15', array['big-dog', 'in-foster', 'shy', 'affectionate']::text[], 'Available', 'Viper sounds like a name for a tough guy, but this dog is anything but. This sweet, adorable goofball is a gentle giant-all 93 lbs of him! He doesn''t walk so much as amble. He''s slow and steady, no breaking speed limits with him. He''s 4 yrs old, tall, dark, handsome and has a regal demeanor. He''s also smart and showed volunteers his mastery of several commands: sit, paw, come and down. Personality-wise, he''s a real people dog and will lean into you for some lovin'' or give shy little kisses. If you want to die of cuteness every time a siren passes your home, you must adopt him! His howling at sirens involves lots of open mouth with very little sound coming out and it''s incredibly adorable and hilarious. Viper is the total package, the real deal. Handsome, smart, friendly, and funny. Get off the dating apps and take him home instead. Come meet this gentle giant today!', false, 'Male', 'Extra large', 'Black and white', 112, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61202963&cid=97&tid=Dog', '61202963', 'dekalb/61202963/1.jpg', array['dekalb/61202963/2.jpg', 'dekalb/61202963/3.jpg']::text[]),
  (md5('dekalb:61625045')::uuid, 'Mika', 'Cat', 'Mixed breed', '3 months', '2026-08-25', array['kitten', 'in-foster']::text[], 'Available', 'Mika is a 3 months old female cat with a Brown and black coat. Come meet Mika at the shelter, or ask about taking Mika home.', false, 'Female', 'Medium', 'Brown and black', 2, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61625045&cid=97&tid=Cat', '61625045', 'dekalb/61625045/1.jpg', '{}'::text[]),
  (md5('dekalb:61827403')::uuid, 'Chesney', 'Dog', 'Mixed breed', '3 years', '2026-09-30', array['big-dog']::text[], 'Available', 'Chesney is a 3 years old female dog with a Black and brown coat. Come meet Chesney at the shelter, or ask about taking Chesney home.', true, 'Female', 'Large', 'Black and brown', 56, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61827403&cid=97&tid=Dog', '61827403', 'dekalb/61827403/1.jpg', array['dekalb/61827403/2.jpg']::text[]),
  (md5('dekalb:61861100')::uuid, 'Fuerte', 'Dog', 'Mixed breed', '7 years', '2026-10-05', '{}'::text[], 'Available', 'Fuerte is a 7 years old male dog with a Black and white coat. Come meet Fuerte at the shelter, or ask about taking Fuerte home.', true, 'Male', 'Medium', 'Black and white', 41, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61861100&cid=97&tid=Dog', '61861100', 'dekalb/61861100/1.jpg', array['dekalb/61861100/2.jpg', 'dekalb/61861100/3.jpg']::text[]),
  (md5('dekalb:57573942')::uuid, 'Titus', 'Dog', 'Mixed breed', '4 years 9 months', '2025-08-18', array['big-dog', 'in-foster', 'shy', 'affectionate']::text[], 'Available', 'Titus has been so scared in the shelter. It''s heartbreaking to see him literally shaking in his kennel. Volunteers and staff have been working with him and he has made enormous improvements. We see a wonderful pup with so much potential who just needs to get out of the shelter and into a loving home which will help build his confidence. One volunteer called him an absolute angel, so affectionate and gentle. Another said "Shy but very cuddly. He was super affectionate and sweet. He''s super gentle and takes his treats gently. Very low energy." When Titus looks up at you pleadingly with his big brown eyes, it''s hard not to be moved. Let Titus move YOU to bring him home.', false, 'Male', 'Large', 'Tan', 60, 'Yes', 'Unknown', 'Unknown', 'Unknown', 'Low', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=57573942&cid=97&tid=Dog', '57573942', 'dekalb/57573942/1.jpg', array['dekalb/57573942/2.jpg', 'dekalb/57573942/3.jpg']::text[]),
  (md5('dekalb:61260282')::uuid, 'Urniemurnie', 'Dog', 'Mixed breed', '4 years 4 months', '2026-06-23', array['big-dog', 'affectionate']::text[], 'Available', '"Urniemurnie here, and I have just 2 requests: I would love a new home and when I get there, please choose a new name for me! Here''s some inside information on me: I''m 4 years old and a big fella, but I love to take walks and I stay by your side nicely. If you want to take a jog, I''ll jog along. I hear that I''m a ''super-holder'' because I keep my kennel clean. I''ll share kisses with you because I love being with people and I really want a home. Treats are happily accepted, but I won''t beg for them. Signed, Your new Best Friend!" Come meet this sweet, big guy and take him home!', true, 'Male', 'Extra large', 'Chocolate and white', 75, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61260282&cid=97&tid=Dog', '61260282', 'dekalb/61260282/1.jpg', array['dekalb/61260282/2.jpg', 'dekalb/61260282/3.jpg']::text[]),
  (md5('dekalb:61928752')::uuid, 'Blizzard', 'Dog', 'Mixed breed', '1 year', '2026-10-19', array['big-dog', 'in-foster']::text[], 'Available', 'Blizzard is a 1 year old male dog with a White coat. Come meet Blizzard at the shelter, or ask about taking Blizzard home.', false, 'Male', 'Large', 'White', 64, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Foster home', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61928752&cid=97&tid=Dog', '61928752', 'dekalb/61928752/1.jpg', array['dekalb/61928752/2.jpg', 'dekalb/61928752/3.jpg']::text[]),
  (md5('dekalb:61922011')::uuid, 'Cookies And Cream', 'Cat', 'Mixed breed', '2 months', '2026-10-17', array['kitten']::text[], 'Available', 'Cookies And Cream is a 2 months old male cat with a Black and white coat. Come meet Cookies And Cream at the shelter, or ask about taking Cookies And Cream home.', true, 'Male', 'Small', 'Black and white', 2, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61922011&cid=97&tid=Cat', '61922011', 'dekalb/61922011/1.jpg', array['dekalb/61922011/2.jpg']::text[]),
  (md5('dekalb:61549713')::uuid, 'Chadwick', 'Dog', 'Mixed breed', '6 years 2 months', '2026-08-12', array['big-dog', 'affectionate', 'house-trained']::text[], 'Available', 'Six year old Chadwick has likely been in a home before so he will adapt easily to a new one. He is super sweet, knows sit and paw and he gives kisses. We think he is also a "closet" cuddle bug - you''ll see. The way to his heart is with treats which he loves loves loves! A volunteer said, "he enjoyed roaming the yard and definitely seems potty trained. Sweet and easygoing personality!" Like we said - you''ll see. Come meet him.', true, 'Male', 'Large', 'Charcoal and white', 54, 'No', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61549713&cid=97&tid=Dog', '61549713', 'dekalb/61549713/1.jpg', array['dekalb/61549713/2.jpg', 'dekalb/61549713/3.jpg']::text[]),
  (md5('dekalb:61514347')::uuid, 'Hollie', 'Dog', 'Mixed breed', '3 years 2 months', '2026-08-06', array['affectionate']::text[], 'Available', 'Hollie is a wiggly, friendly girl who is eager for love and treats. Volunteers were wowed by her lovable personality when they took her out for her photoshoot. She loved rolling on her back and would literally grin from ear to ear. She walks nicely on leash and has figured out that pockets can be a goldmine for hidden treats. As soon as she saw hands in pockets, she knew she had a reward coming! Hollie deserves more than a few treats after being a victim of animal cruelty. She is so sweet and resilient and at 3 years old it''s time for her to experience a real home, a loving home. This precious girl is ready to jump into your car and start a new chapter. Let''s give her a happy beginning!', true, 'Female', 'Medium', 'Black and white', 42, 'Yes', 'Unknown', 'Unknown', 'Unknown', '', 'Shelter', 'DeKalb County Animal Services', 'https://dekalbanimalservices.com/pet-details/?aid=61514347&cid=97&tid=Dog', '61514347', 'dekalb/61514347/1.jpg', array['dekalb/61514347/2.jpg', 'dekalb/61514347/3.jpg']::text[])
